const j=require('./outputs/review_replies.json');
const raw=require('./input/gh-1198/pr_discussions_raw.json');
const t=raw.threads[0];
const r=j.replies[0];
if(j.replies.length!==raw.threads.length) throw new Error('reply count mismatch');
if(r.threadId!==t.threadId) throw new Error('threadId mismatch');
if(r.inReplyToId!==t.rootCommentId) throw new Error('inReplyToId mismatch');
const fs=require('fs');
if(!fs.existsSync(r.reply)) throw new Error('reply file missing');
console.log('OK: 1 reply, threadId verbatim, inReplyToId='+r.inReplyToId+', file exists');
"
echo "== 2. required response.md sections =="; grep -c "^## Issues/Notes\|^## Approach\|^## Files Modified\|^## Test Coverage" outputs/response.md
