echo "== 4. completion guard =="; git log origin/main..HEAD --oneline | wc -l
echo "== 5. final fix content on HEAD =="; grep -n "leavesScalar ? { leavesScalar: true } : null\|if (!ctx.match) continue" js/workflowLint.js

